use strict;
use warnings;
use ExtUtils::MakeMaker;

WriteMakefile(
    NAME             => 'Acme::Units',
    VERSION_FROM     => 'lib/Acme/Units.pm',
    MIN_PERL_VERSION => '5.008001',
    PREREQ_PM        => {  },
    TEST_REQUIRES    => { 'Test::More' => '0.88' },
);

package Acme::Units;
use strict;
use warnings;

our $VERSION = '0.01';

sub km {
    my ($class, $m) = @_;
    return $m / 1000;
}

1;
